import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen0Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }



    @Test
    public void testRemoveColumn_NonExistentColumn() {
        // Setup data
        Comparable row1 = "Row1";
        Comparable col1 = "Col1";
        dataset.addValue(10.0, row1, col1);

        int initialColumnCount = dataset.getColumnCount();
        int initialRowCount = dataset.getRowCount();

        // Execute with a key that doesn't exist
        dataset.removeColumn("NonExistent");

        // Verify nothing changed
        assertEquals(initialColumnCount, dataset.getColumnCount());
        assertEquals(initialRowCount, dataset.getRowCount());
        assertEquals(10.0, dataset.getValue(row1, col1).doubleValue(), 0.001);
    }






}

